WITH sales_by_seg AS ( SELECT hd.hd_income_band_sk, hd.hd_vehicle_count, i.i_category, SUM(cs.cs_ext_sales_price) AS total_sales, SUM(cs.cs_quantity) AS total_quantity, COUNT(DISTINCT cs.cs_order_number) AS orders_sold FROM catalog_sales cs JOIN household_demographics hd ON cs.cs_bill_hdemo_sk = hd.hd_demo_sk JOIN item i ON cs.cs_item_sk = i.i_item_sk GROUP BY hd.hd_income_band_sk, hd.hd_vehicle_count, i.i_category ), returns_by_seg AS ( SELECT hd.hd_income_band_sk, hd.hd_vehicle_count, i.i_category, SUM(cr.cr_return_amount) AS total_return_amount, SUM(cr.cr_return_quantity) AS total_return_qty, COUNT(DISTINCT cr.cr_order_number) AS orders_returned FROM catalog_returns cr JOIN household_demographics hd ON cr.cr_refunded_hdemo_sk = hd.hd_demo_sk JOIN item i ON cr.cr_item_sk = i.i_item_sk GROUP BY hd.hd_income_band_sk, hd.hd_vehicle_count, i.i_category ) SELECT s.hd_income_band_sk, s.hd_vehicle_count, s.i_category, s.total_sales, s.total_quantity, COALESCE(r.total_return_amount, 0) AS total_return_amount, COALESCE(r.total_return_qty, 0) AS total_return_qty, CASE WHEN s.total_quantity = 0 THEN 0 ELSE COALESCE(r.total_return_qty, 0) / NULLIF(s.total_quantity, 0) END AS return_rate, DENSE_RANK() OVER (PARTITION BY s.hd_income_band_sk ORDER BY CASE WHEN s.total_quantity = 0 THEN 0 ELSE COALESCE(r.total_return_qty, 0) / NULLIF(s.total_quantity, 0) END DESC) AS return_rate_rank_in_income_band, CASE WHEN CASE WHEN s.total_quantity = 0 THEN 0 ELSE COALESCE(r.total_return_qty, 0) / NULLIF(s.total_quantity, 0) END > 0.2 THEN 'HIGH' WHEN CASE WHEN s.total_quantity = 0 THEN 0 ELSE COALESCE(r.total_return_qty, 0) / NULLIF(s.total_quantity, 0) END > 0.1 THEN 'MEDIUM' ELSE 'LOW' END AS return_rate_category FROM sales_by_seg s LEFT JOIN returns_by_seg r ON s.hd_income_band_sk = r.hd_income_band_sk AND s.hd_vehicle_count = r.hd_vehicle_count AND s.i_category = r.i_category ORDER BY s.hd_income_band_sk, return_rate DESC LIMIT 100
